    const yScale = d3.scaleLinear()
      .domain([0, n - 1])
      .range([margin.top + nodeRadius, height - margin.bottom - nodeRadius]);
    return d3.range(n).map(i =&gt; yScale(i));
  };

  // Draw connections
  for (let l = 1; l &lt; layers.length; l++) {
    const prevY = getYPositions(layers[l - 1]);
